def main():
    n = int(sys.stdin.readline())
    shop_masks = []
    for _ in range(n):
        f = list(map(int, sys.stdin.readline().split()))
        mask = 0
        for j in range(5):
            for k in range(2):
                if f[j*2 + k] == 1:
                    bit_index = j * 2 + k
                    mask |= (1 << bit_index)
        shop_masks.append(mask)

    p_values = []
    for _ in range(n):
        p = list(map(int, sys.stdin.readline().split()))
        p_values.append(p)

    max_profit = -float('inf')
    for mask in range(1, 1 << 10):
        total = 0
        for i in range(n):
            overlap = mask & shop_masks[i]
            c_i = bin(overlap).count('1')
            total += p_values[i][c_i]
        if total > max_profit:
            max_profit = total

    print(max_profit)

