import sys

def main():
    K = int(sys.stdin.readline())
    max_n = K

    # Step 1: Compute smallest prime factors (spf)
    spf = [0] * (max_n + 1)
    for i in range(2, max_n + 1):
        if spf[i] == 0:
            spf[i] = i
            for j in range(i * 2, max_n + 1, i):
                if spf[j] == 0:
                    spf[j] = i

    # Step 2: Compute Möbius function
    mu = [1] * (max_n + 1)
    for n in range(2, max_n + 1):
        x = n
        factors = set()
        flag = False
        while x != 1:
            p = spf[x]
            if p in factors:
                flag = True
                break
            factors.add(p)
            x //= p
            if x % p == 0:
                flag = True
                break
        if flag:
            mu[n] = 0
        else:
            mu[n] = (-1) ** len(factors)

    # Step 3: Compute the final sum
    total = 0
    for d in range(1, K + 1):
        m = K // d
        sum_h = 0
        for g in range(1, m + 1):
            term = mu[g] * ( (m // g) ) ** 3
            sum_h += term
        total += d * sum_h

    print(total)

